            if (uamm3HavCentralCuFt() != 8) ++bad;
            if (uamm3HavCentralLbs() != 80) ++bad;
            if (!uamm3HavSoughtItemOnTop()) ++bad;
            if (uamm3HavSaveBonus() != 2) ++bad;
            // the central portion is
