            // count
            if (4 * uamm3HavSidePouchCuFt()
                    != uamm3HavCentralCuFt()) ++bad;
            if (4 * uamm3HavSidePouchLbs()
                    != uamm3HavCentralLbs()) ++bad;
            if (uamm3HavSaveBonus()
                    != uamm3HavSidePouches()) ++bad;
        // ---- the horn of fog ----
            if (!uamm3HfgSmallBuglelike()) ++bad;
