            if (uamwBsiExtraDmgPerDiffPoint()
                    != 2) ++bad;
            if (uamwBsiExampleMinToHit() != 12)
                ++bad;
            if (uamwBsiExampleRoll13Dmg() != 2)
                ++bad;
            if (uamwBsiExampleRoll14Dmg() != 4)
                ++bad;
            if (uamwBsiExampleRoll15Dmg() != 8)
                ++bad;
            if (uamwBsiBaseDmgSmLo() != 2) ++bad;
