            if (uaaspPartCleanCount()
                    != uaaspPartItemTotal())
                ++bad;
            if (uaaspPartFlaggedCount()
                    != 0) ++bad;
            if (uamwPartCleanCount()
                    != uamwPartItemTotal())
                ++bad;
            if (uamwPartFlaggedCount()
                    != 0) ++bad;
        printf("R399 UA armor weapons holes pin audit: bad %d\n", bad);
        if (bad) return 1;
