    // ---- R400: the UA comeliness
    // site audit ----
    // The deferred seam closes: the
    // Character field, the creation roll
    // and the parley-gate reaction
    // callers read the R322 pins. The
    // save line and the load tag are
    // splice-assert verified (the
    // battery never writes adnd1.sav).
    {
        using namespace rules;
        int bad = 0;
        // the score helper: the raw 3d6
        // plus the charisma ladder; 0 =
        // unknown reads 0 (the v1-save
        // read); cha below 3 reads -8
        if (uaComelinessScore(0, 12) != 0)
            ++bad;
        if (uaComelinessScore(3, 12) != 3)
            ++bad;
        if (uaComelinessScore(3, 3) != -2)
            ++bad;
        if (uaComelinessScore(3, 2) != -5)
            ++bad;
        if (uaComelinessScore(18, 18) != 21)
            ++bad;
        if (uaComelinessScore(18, 19) != 23)
            ++bad;
        // the print dwarf example (base
        // 9, cha 16): the score reads 11
        // (the print own at-8 cell is the
        // loose arithmetic)
        if (uaComelinessScore(9, 16) != 11)
            ++bad;
        // the viewed score: the same-race
        // pairs read 0 (the print
        // halfling/human and the
        // sylvan-elf/half-elf pairs)
        if (uaComelinessEffective(11, RACE_DWARF,
                                 RACE_DWARF) != 11)
            ++bad;
        if (uaComelinessEffective(11, RACE_DWARF,
                                 RACE_HUMAN) != 10)
            ++bad;
        if (uaComelinessEffective(11, RACE_HUMAN,
                                 RACE_HALFLING) != 11)
            ++bad;
        if (uaComelinessEffective(11, RACE_HALFLING,
                                 RACE_HUMAN) != 11)
            ++bad;
        if (uaComelinessEffective(11, RACE_HALF_ELF,
                                 RACE_ELF) != 11)
            ++bad;
        if (uaComelinessEffective(11, RACE_ELF,
                                 RACE_HALF_ELF) != 11)
            ++bad;
        if (uaComelinessEffective(11, RACE_HALF_ORC,
                                 RACE_HUMAN) != 8)
            ++bad;
        // the unknown member views 0 (the
        // v1-save read)
        if (uaComelinessEffective(0, RACE_DWARF,
                                 RACE_HUMAN) != 0)
            ++bad;
        // the monster-viewer read: the
        // viewed-race adjustment always
        // rides (the site convention)
        if (uaComelinessScoreOtherRace(9, 16,
                                      RACE_DWARF) != 10)
            ++bad;
        if (uaComelinessScoreOtherRace(9, 16,
                                      RACE_HUMAN) != 11)
            ++bad;
        if (uaComelinessScoreOtherRace(0, 12,
                                      RACE_ELF) != 0)
            ++bad;
        // the initial-contact percentile:
        // 100 at 14-17, 150 at 18-21, 200
        // at 22 and up (the print 22
        // comeliness equals +44%); the
        // bands below interest carry no
        // percentile
        if (uaComelinessReactionAdj(-5) != 0)
            ++bad;
        if (uaComelinessReactionAdj(10) != 0)
            ++bad;
        if (uaComelinessReactionAdj(13) != 0)
            ++bad;
        if (uaComelinessReactionAdj(14) != 14)
            ++bad;
        if (uaComelinessReactionAdj(16) != 16)
            ++bad;
        if (uaComelinessReactionAdj(17) != 17)
            ++bad;
        if (uaComelinessReactionAdj(18) != 27)
            ++bad;
        if (uaComelinessReactionAdj(21) != 31)
            ++bad;
        if (uaComelinessReactionAdj(22) != 44)
            ++bad;
        if (uaComelinessReactionAdj(25) != 50)
            ++bad;
        if (uaComelinessReactionAdj(26) != 52)
            ++bad;
        // ---- the cross-checks ----
        // the stunning and unearthly
        // ladders double the score
        if (2 * 22 != uaComelinessReactionAdj(22))
            ++bad;
        if (2 * 26 != uaComelinessReactionAdj(26))
            ++bad;
        // the unknown member never moves
        // a reaction
        if (uaComelinessReactionAdj(
                uaComelinessScore(0, 12)) != 0)
            ++bad;
        // ---- the wiring ----
        // the creation roll rides the
        // member; a fresh Character reads
        // unknown (the v1-save read)
        {
            CreationState cr;
            cr.rollFresh();
            if (cr.uaComRoll < 3
                || cr.uaComRoll > 18) ++bad;
            Character c = cr.makeMember(0);
            if (c.uaComBase != cr.uaComRoll)
                ++bad;
            Character d;
            if (d.uaComBase != 0) ++bad;
        }
        printf("R400 UA comeliness site audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R401: the UA cantrip tier
    // seam audit ----
    // The sub-1st registry tier closes the
    // deferred seam: the p. 45 tier traits,
    // the 0-level per-day ladder, the
    // first-level retention, the round
    // rules and the roster; the R341
    // decode amendments cross-check here.
    {
        using namespace rules;
        int bad = 0;
        // the tier traits
        if (cantSpellLevel() != 0) ++bad;
        if (cantRangeInches() != 1) ++bad;
        if (cantCastTimeMinTenths() != 1)
            ++bad;
        if (cantCastTimeMaxTenths() != 5)
            ++bad;
        if (!cantSmallAoe()) ++bad;
        if (!cantSoftSimpleComponents())
            ++bad;
        if (!cantLivingCreatureCantripsAllowSave()) ++bad;
        if (!cantConcentrationBlocksPersonAffecting()) ++bad;
        if (!cantFaintMagicAura()) ++bad;
        if (!cantMemorizedLikeSpells())
            ++bad;
        // the per-day ladder: the band
        // edges
        if (cantPerDayByXp(-2000) != 1)
            ++bad;
        if (cantPerDayByXp(-1001) != 1)
            ++bad;
        if (cantPerDayByXp(-1000) != 2)
            ++bad;
        if (cantPerDayByXp(-501) != 2)
            ++bad;
        if (cantPerDayByXp(-500) != 3)
            ++bad;
        if (cantPerDayByXp(-1) != 3)
            ++bad;
        if (cantPerDayByXp(0) != 0) ++bad;
        if (cantPerDayByXp(500) != 0)
            ++bad;
        if (cantPerDayByXp(-2001) != 1)
            ++bad;
        // the ladder agrees with its bands
        if (cantNeophytePerDay()
                != cantPerDayByXp(
                      cantNeophyteXpHi()))
            ++bad;
        if (cantInitiatePerDay()
                != cantPerDayByXp(                      cantInitiateXpHi()))
            ++bad;
        if (cantApprenticePerDay()
                != cantPerDayByXp(                      cantApprenticeXpHi()))
            ++bad;
        // the bands tile contiguously
        if (cantInitiateXpLo()
                != cantNeophyteXpHi() + 1)
            ++bad;
        if (cantApprenticeXpLo()
                != cantInitiateXpHi() + 1)
            ++bad;
        // the per-day ladder climbs
        if (cantNeophytePerDay() + 1
                != cantInitiatePerDay())
            ++bad;
        if (cantInitiatePerDay() + 1
                != cantApprenticePerDay())
            ++bad;
        // the first-level retention
        if (!cantKnowledgeDiscardedAtFirst()) ++bad;
        if (cantRetainedMaxInPlaceOfFirst()
            != 4) ++bad;
        // the round rules
        if (cantPerRoundMax() != 2) ++bad;
        if (cantSecondCastGapDieSides()
            != 4) ++bad;
        if (!cantNoSpellAndCantripSameRound()) ++bad;
        // the categories
        if (cantCategoryCount() != 7)
            ++bad;
        if (cantMuCategoryCount() != 6)
            ++bad;
        if (cantCategoryCount()
                != cantMuCategoryCount() + 1)
            ++bad;
        if (!cantAnyCasterMayKnowAllCategories()) ++bad;
        // the roster (the R401-amended
        // R341 decode)
        if (cantMuRosterTotal() != 66)
            ++bad;
        if (cantIlRosterTotal() != 8)
            ++bad;
        if (cantRosterTotal()
                != cantMuRosterTotal()
                   + cantIlRosterTotal())
            ++bad;
        {
            int total = 0;
            for (int c = 0; c < 6; ++c)
                total += uastCantripCount(c);
            if (total != cantMuRosterTotal())
                ++bad;
        }
        // the R341 seam agreement: the
        // category counts and the
        // amended name seats
        if (uastCantripCount(1) != 12)
            ++bad;
        if (uastCantripCount(4) != 10)
            ++bad;
        if (strcmp(uastCantripName(1, 8),
            "Tangle") != 0) ++bad;
        if (strcmp(uastCantripName(4, 8),
            "Tweak") != 0) ++bad;
        if (uastCantripName(1, 12)[0] != 0)
            ++bad;
        if (uastCantripName(4, 10)[0] != 0)
            ++bad;
        // the R369/R365 acquisition seams
        if (uacaqCategoryCount()
                != cantMuCategoryCount())
            ++bad;
        if (uacaqMaxDevelopedCantrips()
                != uastMuCantripMaxNewCount())
            ++bad;
        if (uastIlMinorIllusionMin()
                > uastIlMinorIllusionMax())
            ++bad;
        if (uastIlMinorIllusionMax()
                > cantIlRosterTotal()) ++bad;
        // the R366 book seam
        if (!uabkCantripsCountAsFirstLevel())
            ++bad;
        // the R363 minor-illusion roster
        if (strcmp(uailcLightsName(),
            "Colored Lights (Alteration)") != 0)
            ++bad;
        if (strcmp(uailcDimName(),
            "Dim (Alteration)") != 0) ++bad;
        if (strcmp(uailcHazeName(),
            "Haze (Alteration)") != 0) ++bad;
        if (strcmp(uailcMaskName(),
            "Mask (Illusion)") != 0) ++bad;
        if (strcmp(uailcMirageName(),
            "Mirage") != 0) ++bad;
        if (strcmp(uailcNoiseName(),
            "Noise (Illusion)") != 0) ++bad;
        if (strcmp(uailcRainbowName(),
            "Rainbow (Alteration)") != 0)
            ++bad;
        if (strcmp(uailcTwodName(),
            "Two-D'lusion") != 0)
            ++bad;
        printf("R401 UA cantrip tier seam audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R402: the UA treasure
    // dial seam audit ----
    // The R374 decision wires: the
    // dial state (DMG the default,
    // UA, MERGED), the UA-mode
    // determination dispatch (the
    // R375/R395 data rides the
    // engine roller - the category
    // bands, the sub-table splits,
    // the misc seven sub-bands, the
    // row resolution), and the
    // MERGED union read. The DMG
    // audits stay authoritative
    // (the default mode); census
    // 328 -> 329.
    {
        using namespace rules;
        int bad = 0;
        // ---- the dial state ----
        if (uatdMode() != uatdModeDmg()) ++bad;
        if (strcmp(uatdModeName(0),
                   "DMG") != 0) ++bad;
        if (strcmp(uatdModeName(1),
                   "UA") != 0) ++bad;
        if (strcmp(uatdModeName(2),
                   "MERGED") != 0) ++bad;
        if (!uatdModeValid(0)
                || !uatdModeValid(2)) ++bad;
        if (uatdModeValid(3)
                || uatdModeValid(-1)) ++bad;
        uatdSetMode(uatdModeUa());
        if (uatdMode() != uatdModeUa()) ++bad;
        uatdSetMode(99);
        if (uatdMode() != uatdModeDmg()) ++bad;
        if (uatdUaPinRoundsPending()) ++bad;
        if (!uatdDialLanded()) ++bad;
        // ---- the UA row data ----
        // every table covers 01-00
        // contiguously (the band walk)
        for (int t = 0;
             t < uadrowTableCount(); ++t) {
            if (uadrowRowLo(t, 0) != 1) ++bad;
            if (uadrowRowHi(t,
                    uadrowRowCount(t) - 1)
                    != 100) ++bad;
            for (int i = 0;
                 i + 1 < uadrowRowCount(t);
                 ++i)
                if (uadrowRowLo(t, i + 1)
                        != uadrowRowHi(t, i) + 1)
                    ++bad;
        }
        // the spot rows (the R395 pins)
        if (strcmp(uadrowRowName(0, 0),
                   "Animal Control") != 0) ++bad;
        if (strcmp(uadrowRowName(17, 0),
                   "Sword + 1") != 0) ++bad;
        if (strcmp(uadrowRowName(6, 0),
                   "Rod of Absorption") != 0)
            ++bad;
        if (strcmp(uadrowRowName(19, 0),
                   "Arrow + 1, 2-24 in number")
                != 0) ++bad;
        // ---- the UA-mode dispatch ----
        // statistical: every category
        // serves, the misc always the
        // UA sub-tables
        rules::Rng rngUa(402);
        rules::Dice diceUa(rngUa);
        uatdSetMode(uatdModeUa());
        int uaPot = 0, uaMisc = 0;
        for (int i = 0; i < 20000; ++i) {
            dm::treasure::MagicItem m =
                dm::treasure::rollMagicItem(
                    diceUa);
            if (m.name.empty()
                    || m.category < 0
                    || m.category > 11) ++bad;
            if (m.category == 0) ++uaPot;
            if (m.category == 8) ++uaMisc;
        }
        if (uaPot == 0 || uaMisc == 0) ++bad;
        // the potion band is 20 percent,
        // the misc band 15 - loose
        // bounds catch the routing
        if (uaPot < 1000
                || uaPot > 9000) ++bad;
        if (uaMisc < 1000
                || uaMisc > 9000) ++bad;
        // ---- the MERGED union ----
        rules::Rng rngM(403);
        rules::Dice diceM(rngM);
        uatdSetMode(uatdModeMerged());
        for (int i = 0; i < 20000; ++i) {
            dm::treasure::MagicItem m =
                dm::treasure::rollMagicItem(
                    diceM);
            if (m.name.empty()
                    || m.category < 0
                    || m.category > 11) ++bad;
        }
        // ---- the DMG default restores ----
        uatdSetMode(uatdModeDmg());
        if (uatdMode() != uatdModeDmg()) ++bad;
        printf("R402 UA treasure dial seam audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R403: the mount layer
    // seam audit ----
    // The deferred seam lands: the
    // layer contract (no mount
    // actor site; the pins precede
    // the site; the seam gates the
    // mounted-combat charge) and
    // the live cross-checks of the
    // six feeders - R123 the
    // mounted movement, R170 the
    // followers mounts, R189 the
    // charge damage, R321 the
    // aerial environment, R328 the
    // cavalier mounted reads, R356
    // the mount spell. The flying
    // steed ladder cross-declares
    // against the cavalier
    // horsemanship tail; census
    // 329 -> 330.
    {
        using namespace rules;
        int bad = 0;
        // ---- the layer contract ----
        if (mmlMountActorSiteExists()) ++bad;
        if (!mmlPinsPrecedeSite()) ++bad;
        if (!mmlGatesMountedCombatCharge()) ++bad;
        if (!mmlMountedCombatChargeOpen()) ++bad;
        if (mmlAerialPrecedentRound() != 321) ++bad;
        // ---- the feeder registry ----
        if (mmlFeederSeamCount() != 6) ++bad;
        if (mmlFeederRound(0) != 123
                || mmlFeederRound(1) != 170
                || mmlFeederRound(2) != 189)
            ++bad;
        if (mmlFeederRound(3) != 321
                || mmlFeederRound(4) != 328
                || mmlFeederRound(5) != 356)
            ++bad;
        // ---- the R189 charge seam ----
        if (lanceChargingDouble(23)) ++bad;
        if (!lanceChargingDouble(24)
                || !lanceChargingDouble(25)
                || !lanceChargingDouble(26))
            ++bad;
        if (lanceChargingDouble(27)) ++bad;
        if (!spearSetChargingDouble()) ++bad;
        // ---- the R328 cavalier seam ----
        if (cavalierHumanMountedLevelBonus()
                != 1) ++bad;
        if (cavalierSaddlePercent(1) != 85)
            ++bad;
        if (cavalierSaddlePercent(8) != 92)
            ++bad;
        if (cavalierSteedHpBonusPerDie() != 2)
            ++bad;
        // the flying steed ladder
        // agreement (the mml
        // cross-declaration vs the
        // cavalier horsemanship tail)
        for (int i = 0;
             i < mmlFlyingSteedCount();
             ++i)
            if (mmlFlyingSteedGrantLevel(i)
                    != cavalierHorsemanshipLevel(
                        i + 3))
                ++bad;
        if (mmlFlyingSteedGrantLevel(0) != 7)
            ++bad;
        if (mmlFlyingSteedGrantLevel(2) != 11)
            ++bad;
        if (!mmlFlyingSteedsRideAerialEnv())
            ++bad;
        // ---- the R321 aerial seam ----
        if (aerialClimbRateDivisor() != 2) ++bad;
        if (aerialDiveRateMultiple() != 2) ++bad;
        // ---- the R123 movement seam ----
        if (dm::mountedMilesPerDay(
                dm::MOUNT_LIGHT, dm::TC_NORMAL)
                != 60) ++bad;
        if (dm::mountedMilesPerDay(
                dm::MOUNT_HEAVY,
                dm::TC_VERY_RUGGED) != 5) ++bad;
        if (dm::mountedMilesPerDay(
                dm::MOUNT_WAGON,
                dm::TC_VERY_RUGGED) != 0) ++bad;
        // ---- the R170 followers seam ----
        if (folPaladinWarhorseMinLevel() != 4)
            ++bad;
        if (folPaladinWarhorseServiceYears() != 10)
            ++bad;
        // ---- the R356 spell seam ----
        if (uam1MountLevel() != 1) ++bad;
        if (uam1MountCastingTimeRounds() != 1)
            ++bad;
        if (!uam1MountServesThenReturns()) ++bad;
        if (uam1MountMuleLightHorseMaxLevel()
                != 3) ++bad;
        printf("R403 mount layer seam audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R404: the psionics seam
    // audit ----
    // The deferred seam lands: the
    // layer contract (no psionic site;
    // the pins precede the charge; the
    // seam gates the psionic
    // expansions), the open and OUT
    // records (the PHB sections OPEN;
    // the DMG p.77 combat OUT), the
    // UA pp. 10-11 pins (the duergar
    // doubled chance, the svirfneblin
    // PC ban) and the live
    // cross-checks of the three
    // feeders - R166 the insanity seam,
    // R323 the subrace layer, R328 the
    // cavalier mind powers; census
    // 330 -> 331.
    {
        using namespace rules;
        int bad = 0;
        // ---- the layer contract ----
        if (psxPsionicSiteExists()) ++bad;
        if (!psxPinsPrecedeCharge()) ++bad;
        if (!psxGatesPsionicExpansions()) ++bad;
        if (!psxPsionicChargeOpen()) ++bad;
        // ---- the open and OUT records ----
        if (!psxPhbSectionsOpen()) ++bad;
        if (psxDmgPsionicCombatPage() != 77)
            ++bad;
        if (!psxDmgCombatOutOfScope()) ++bad;
        // ---- the duergar pin ----
        if (!psxDuergarNotAllPsionic()) ++bad;
        if (psxDuergarChanceMultiple() != 2)
            ++bad;
        if (!psxDuergarDoublesIntWisCha()) ++bad;
        if (!psxDuergarDoubledOnlyIfUsed()) ++bad;
        // the doubled bonus arithmetic:
        // every usual bonus doubles
        if (psxDuergarDoubledBonus(1) != 2
                || psxDuergarDoubledBonus(
                    5) != 10
                || psxDuergarDoubledBonus(
                    10) != 20)
            ++bad;
        if (psxDuergarDoubledBonus(0) != 0) ++bad;
        // ---- the svirfneblin pin ----
        if (!psxSvirfneblinPcNoPsionics()) ++bad;
        // ---- the feeder registry ----
        if (psxFeederSeamCount() != 3) ++bad;
        if (psxFeederRound(0) != 166
                || psxFeederRound(1) != 323
                || psxFeederRound(2) != 328)
            ++bad;
        // ---- the R166 insanity seam ----
        // the four MILD forms (1-4) are
        // subject to psionic attack;
        // 5+ are not
        for (int i = 1; i <= 4; ++i)
            if (!insanityIsMild(i)) ++bad;
        if (insanityIsMild(0)
                || insanityIsMild(5)
                || insanityIsMild(20)) ++bad;
        // the duration classes ride the
        // psionic section (2-12 temporary,
        // 1-4 mild)
        if (insanityTemporaryWeeksMin() != 2
                || insanityTemporaryWeeksMax()
                    != 12)
            ++bad;
        if (insanityMildWeeksMin() != 1
                || insanityMildWeeksMax() != 4)
            ++bad;
        // ---- the R323 subrace seam ----
        // the svirfneblin PC ban rides the
        // trait table; the duergar row
        // carries no ban (the not-all
        // read)
        if (subraceTraits(SUB_GNOME_DEEP)
                .noPsionics != 1) ++bad;
        if (subraceTraits(SUB_DWARF_GRAY)
                .noPsionics != 0) ++bad;
        // ---- the R328 cavalier seam ----
        if (cavalierMindAffectResistPercent()
                != 90) ++bad;
        if (strcmp(cavalierMindPowerName(9),
                   "psionic mind blast") != 0)
            ++bad;
        printf("R404 psionics seam audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R405: the deity layer seam
    // audit ----
    // The last in-scope seam lands: the
    // layer contract (no deity site; the
    // pins precede the site; the seam
    // gates the Appendix S charge; the
    // stat blocks stay open), the source
    // pins (Appendix S pp. 109-122,
    // Moradin in Legends & Lore at 20
    // feet), the census (23 deities, 5
    // pantheons 5/5/4/4/5, the tiers
    // 5/16/2, the ratings VI 10 III 5
    // IV 1 Nil 6 + Brandobaris
    // unrecorded), the dwarven reads
    // (twice normal size, no living
    // symbols, dual charismas, the -4
    // giant penalty), the five 8-column
    // charts, and the live cross-checks
    // of the four feeders - R169 the
    // humanoid matrix, R322 the
    // comeliness bands, R323 the
    // subrace parents, R404 the psx
    // pins; census 331 -> 332.
    {
        using namespace rules;
        int bad = 0;
        // ---- the layer contract ----
        if (nhdDeitySiteExists()) ++bad;
        if (!nhdPinsPrecedeSite()) ++bad;
        if (!nhdGatesAppendixS()) ++bad;
        if (!nhdStatBlocksOpen()) ++bad;
        // ---- the source pins ----
        if (nhdAppendixPageFirst() != 109)
            ++bad;
        if (nhdAppendixPageLast() != 122)
            ++bad;
        if (!nhdMoradinInLegendsLore()) ++bad;
        if (nhdMoradinHeightFeet() != 20)
            ++bad;
        // ---- the census pins ----
        if (nhdDeityCount() != 23) ++bad;
        if (nhdPantheonCount() != 5) ++bad;
        // the pantheon sizes: 5/5/4/4/5
        if (nhdPantheonSize(0) != 5
                || nhdPantheonSize(1) != 5
                || nhdPantheonSize(2) != 4
                || nhdPantheonSize(3) != 4
                || nhdPantheonSize(4) != 5)
            ++bad;
        // the pantheons add up to the census
        if (nhdPantheonSize(0)
                + nhdPantheonSize(1)
                + nhdPantheonSize(2)
                + nhdPantheonSize(3)
                + nhdPantheonSize(4)
                != nhdDeityCount()) ++bad;
        // the tiers: 5 greater, 16 lesser,
        // 2 demigods - and they add up
        if (nhdGreaterDeityCount() != 5
                || nhdLesserDeityCount() != 16
                || nhdDemigodCount() != 2)
            ++bad;
        if (nhdGreaterDeityCount()
                + nhdLesserDeityCount()
                + nhdDemigodCount()
                != nhdDeityCount()) ++bad;
        // the ratings: VI 10, III 5, IV 1,
        // Nil 6 - and with Brandobaris
        // unrecorded they add up
        if (nhdPsionicRatingCount(0) != 10
                || nhdPsionicRatingCount(1)
                    != 5
                || nhdPsionicRatingCount(2)
                    != 1
                || nhdPsionicRatingCount(3)
                    != 6)
            ++bad;
        if (nhdPsionicRatingCount(0)
                + nhdPsionicRatingCount(1)
                + nhdPsionicRatingCount(2)
                + nhdPsionicRatingCount(3)
                + nhdRatingUnrecordedCount()
                != nhdDeityCount()) ++bad;
        // ---- the dwarven reads ----
        if (nhdGreaterDwarfSizeMultiple() != 2)
            ++bad;
        if (!nhdDwarfSymbolNeverLiving()) ++bad;
        if (!nhdDwarfDeityDualCharisma()) ++bad;
        if (nhdGiantTypeAttackPenalty() != 4)
            ++bad;
        // ---- the clerical charts ----
        if (nhdChartCount() != 5) ++bad;
        if (nhdChartColumnCount() != 8) ++bad;
        // the charts carry one row per
        // deity: 23 rows across the five
        if (nhdChartCount()
                != nhdPantheonCount()) ++bad;
        // ---- the feeder registry ----
        if (nhdFeederSeamCount() != 4) ++bad;
        if (nhdFeederRound(0) != 169
                || nhdFeederRound(1) != 322
                || nhdFeederRound(2) != 323
                || nhdFeederRound(3) != 404)
            ++bad;
        // ---- the R169 humanoid matrix ----
        // the nine-race matrix carries the
        // orc row but no elf column - the
        // Appendix S Gruumsh/Corellon read
        // is the sole cross-pantheon site
        if (humRPrefRaceCount() != 9) ++bad;
        if (humRPrefRaceIndex("orc") != 7)
            ++bad;
        if (humRPrefRaceIndex("elf") != -1)
            ++bad;
        // ---- the R322 comeliness seam ----
        // Clanggedin CM:13(20) - the dual
        // comeliness values ride the R322
        // bands (13 the band-5 side, 20 the
        // band-7 side at 150 percent)
        if (uaComelinessBand(13) != 5) ++bad;
        if (uaComelinessBand(20) != 7) ++bad;
        if (uaComelinessReactionPct(20)
                != 150) ++bad;
        // ---- the R323 subrace seam ----
        // the four demi-human pantheons map
        // to their subrace parents (orcs
        // carry no subrace)
        if (subraceParentRace(SUB_DWARF_GRAY)
                != RACE_DWARF) ++bad;
        if (subraceParentRace(SUB_ELF_HIGH)
                != RACE_ELF) ++bad;
        if (subraceParentRace(SUB_GNOME_DEEP)
                != RACE_GNOME) ++bad;
        if (subraceParentRace(
                SUB_HALFLING_HAIRFOOT)
                != RACE_HALFLING) ++bad;
        // ---- the R404 psionics seam ----
        // the PC psionic reads stay
        // PC-side: the duergar doubled
        // chance and the svirfneblin ban
        // (the deity ratings are the
        // Appendix S scale, not the PC
        // chance)
        if (psxDuergarChanceMultiple() != 2)
            ++bad;
        if (!psxSvirfneblinPcNoPsionics())
            ++bad;
        printf("R405 deity layer seam audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R406: the UA Appendix S
    // stat blocks pin audit ----
    // The ungated data round rides
    // the R405 seam: the 23 stat
    // blocks pin their scan-clean
    // numerics (tier, AC, HP, MR,
    // rating, size, the attacks in
    // halves, the damage range, the
    // printed alignment and plane),
    // the tier and rating censuses
    // cross-check the R405 seam
    // live, the hole sentinels
    // record the scan garbles, and
    // the 6985 hit-point sum catches
    // any cell drift; the class
    // lines, the MOVE values and the
    // stat lines stay unpinned;
    // census 332 -> 333.
    {
        using namespace rules;
        int bad = 0;
        // ---- the census ----
        if (uasDeityCount() != 23) ++bad;
        if (uasDeityCount()
                != nhdDeityCount()) ++bad;
        // the tier census: 5/16/2
        if (uasTierCount(UAS_TIER_GREATER)
                != 5) ++bad;
        if (uasTierCount(UAS_TIER_LESSER)
                != 16) ++bad;
        if (uasTierCount(UAS_TIER_DEMI)
                != 2) ++bad;
        if (uasTierCount(UAS_TIER_GREATER)
                + uasTierCount(UAS_TIER_LESSER)
                + uasTierCount(UAS_TIER_DEMI)
                != 23) ++bad;
        // the rating census: VI 10,
        // III 5, IV 1, Nil 6,
        // unrecorded 1 - and the four
        // printed codes match the R405
        // seam live
        if (uasRatingCount(UAS_RATING_VI)
                != 10) ++bad;
        if (uasRatingCount(UAS_RATING_III)
                != 5) ++bad;
        if (uasRatingCount(UAS_RATING_IV)
                != 1) ++bad;
        if (uasRatingCount(UAS_RATING_NIL)
                != 6) ++bad;
        if (uasRatingCount(
                UAS_RATING_UNRECORDED) != 1)
            ++bad;
        if (uasRatingCount(UAS_RATING_VI)
                != nhdPsionicRatingCount(0))
            ++bad;
        if (uasRatingCount(UAS_RATING_III)
                != nhdPsionicRatingCount(1))
            ++bad;
        if (uasRatingCount(UAS_RATING_IV)
                != nhdPsionicRatingCount(2))
            ++bad;
        if (uasRatingCount(UAS_RATING_NIL)
                != nhdPsionicRatingCount(3))
            ++bad;
        // the pantheon slices ride the
        // R405 registry live
        if (uasPantheonSize(0)
                != nhdPantheonSize(0)
                || uasPantheonSize(1)
                    != nhdPantheonSize(1)
                || uasPantheonSize(2)
                    != nhdPantheonSize(2)
                || uasPantheonSize(3)
                    != nhdPantheonSize(3)
                || uasPantheonSize(4)
                    != nhdPantheonSize(4))
            ++bad;
        // ---- the drift catch ----
        if (uasTotalHitPoints() != 6985)
            ++bad;
        // ---- the hole sentinels ----
        if (uasAcHoleCount() != 1
                || uasAtkHoleCount() != 1
                || uasDamageUnrecordedCount()
                    != 4)
            ++bad;
        if (uasStat(8).ac != UAS_AC_HOLE)
            ++bad;
        if (uasStat(19).atkHalves
                != UAS_ATK_HOLE) ++bad;
        // ---- the spot checks ----
        // Clanggedin (the first block)
        if (strcmp(uasStat(0).name,
                   "CLANGGEDIN SILVERBEARD") != 0)
            ++bad;
        if (uasStat(0).ac != -4
                || uasStat(0).hp != 375
                || uasStat(0).mr != 50
                || uasStat(0).tier
                    != UAS_TIER_GREATER
                || uasStat(0).rating
                    != UAS_RATING_VI
                || uasStat(0).size
                    != UAS_SIZE_L
                || uasStat(0).atkHalves != 4
                || uasStat(0).dmgMin != 3
                || uasStat(0).dmgMax != 36)
            ++bad;
        if (strcmp(uasStat(0).align,
                   "Lawful neutral") != 0)
            ++bad;
        if (strcmp(uasStat(0).plane,
                   "Arcadia") != 0) ++bad;
        // Berronar, Hanali, Brandobaris
        if (uasStat(4).hp != 370
                || uasStat(4).mr != 80) ++bad;
        if (uasStat(8).hp != 312
                || uasStat(8).mr != 95
                || uasStat(8).dmgMin != 0
                || uasStat(8).dmgMax != 0)
            ++bad;
        if (uasStat(13).hp != 185
                || uasStat(13).tier
                    != UAS_TIER_DEMI
                || uasStat(13).rating
                    != UAS_RATING_UNRECORDED)
            ++bad;
        // Bahgtru, Shargaas, Luthic
        if (uasStat(18).dmgMin != 10
                || uasStat(18).dmgMax != 60)
            ++bad;
        if (uasStat(19).rating
                != UAS_RATING_IV
                || uasStat(19).ac != 2
                || uasStat(19).dmgMin != 3
                || uasStat(19).dmgMax != 30)
            ++bad;
        if (uasStat(22).ac != 3
                || uasStat(22).hp != 287
                || uasStat(22).dmgMin != 5
                || uasStat(22).dmgMax != 20)
            ++bad;
        if (strcmp(uasStat(22).align,
                   "Lawful evil") != 0) ++bad;
        // Urdlen: the evil gnome
        if (strcmp(uasStat(15).plane,
                   "Abyss") != 0) ++bad;
        printf("R406 UA appendix S stat blocks pin audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R407: the UA Appendix S
