        // (one-tenth) than the unsaved short fall (one-half), over a higher
        // threshold
    if (wmwFallSaveMaxFt() <= wmwFallSaveMinFt()
            || wmwLongFallDiv() <= wmwFallDamageDiv()
        )
            ++bad;
